def prefix_xor(a):
    p = [0]
    for x in a:
        p.append(p[-1] ^ x)
    return p


def xor_range(p, l, r):                # xor of a[l:r], eq-pref-xor
    return p[l] ^ p[r]


def xor_brute(a, l, r):
    out = 0
    for x in a[l:r]:
        out ^= x
    return out


for _ in range(800):
    a = [random.randint(0, 60) for _ in range(random.randint(0, 12))]
    p = prefix_xor(a)
    for _ in range(20):
        l = random.randint(0, len(a)); r = random.randint(l, len(a))
        assert xor_range(p, l, r) == xor_brute(a, l, r)

px = prefix_xor([1, 3, 4, 8])
print("prefix xor of [1,3,4,8]:", px)
assert xor_range(px, 0, 2) == 2 and xor_range(px, 1, 3) == 7
print("xor prefix table agrees with the nested loop")


def leaders(a):
    """Indices whose value is >= every value to their right: a suffix maximum."""
    out, best = [], -math.inf
    for i in range(len(a) - 1, -1, -1):
        if a[i] >= best:
            out.append(i)
            best = a[i]
    return out[::-1]


assert leaders([16, 17, 4, 3, 5, 2]) == [1, 4, 5]      # the values 17, 5, 2
assert leaders([1, 2, 3]) == [2]
assert leaders([5, 5, 5]) == [0, 1, 2]
print("leaders (suffix maxima) OK")
```

