#include <vector>
using namespace std;

int subarraysDivByK(vector<int>& nums, int k) {
    vector<int> cnt(k, 0);
    cnt[0] = 1;
    long long ans = 0;
    int r = 0;
    for (int x : nums) {
        r = ((r + x) % k + k) % k;      // C++ % can be negative: normalise!
