#include <vector>
#include <algorithm>
using namespace std;

int maxSideLength(vector<vector<int>>& mat, int threshold) {
    int m = mat.size(), n = mat[0].size();
    vector<vector<int>> p(m + 1, vector<int>(n + 1, 0));
    for (int i = 0; i < m; ++i) {
        int rowsum = 0;
        for (int j = 0; j < n; ++j) {
            rowsum += mat[i][j];
            p[i + 1][j + 1] = p[i][j + 1] + rowsum;
        }
    }
    auto fits = [&](int s) {
        for (int i = s; i <= m; ++i)
            for (int j = s; j <= n; ++j)
                if (p[i][j] - p[i - s][j] - p[i][j - s] + p[i - s][j - s] <= threshold)
                    return true;
        return false;
    };
    int best = 0;
    for (int s = 1; s <= min(m, n); ++s) {
        if (!fits(s)) break;
        best = s;
    }
    return best;
}
