##### C++

```cpp
#include <vector>
using namespace std;

vector<int> xorQueriesBrute(vector<int>& arr, vector<vector<int>>& queries) {
    vector<int> ans;
    for (auto& qu : queries) {
        int x = 0;
        for (int k = qu[0]; k <= qu[1]; ++k) x ^= arr[k];
        ans.push_back(x);
    }
    return ans;
}
```
